export const GENSYS_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/gensys-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getGensysStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(GENSYS_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
